<script setup lang="ts">
import { ALLERGENS, getAllergenConfig, setAllergenConfig, getConfig, setConfig, fetchSchoolDefaultInfo } from '~/lib/apiHandlerV2'
const state = reactive({ atptOfcdcScCode: '', sdSchulCode: '' }); const school = reactive({ cityProvince: '', schoolName: '' }); const selected = ref<number[]>([]); const open = ref(false); const toast = useToast()
const selections = reactive<Record<number, boolean>>({})
onMounted(() => { const config = getConfig(); state.atptOfcdcScCode = config.atptOfcdcScCode; state.sdSchulCode = config.sdSchulCode; selected.value = getAllergenConfig(); ALLERGENS.forEach((item) => selections[item.code] = selected.value.includes(item.code)) })
const save = () => { selected.value = ALLERGENS.filter((item) => selections[item.code]).map((item) => item.code); setAllergenConfig(selected.value); setConfig(state.atptOfcdcScCode, state.sdSchulCode); toast.add({ title: '설정 저장 완료', description: '메뉴 화면에 알레르기 주의 표시가 적용됩니다.', color: 'success' }) }
const findSchool = async () => { const result = await fetchSchoolDefaultInfo(school.cityProvince, school.schoolName); if (typeof result === 'string' || !result) { toast.add({ title: '학교를 찾지 못했어요', description: '시도와 학교 이름을 확인해 주세요.', color: 'error' }); return }; state.atptOfcdcScCode = result.ATPT_OFCDC_SC_CODE; state.sdSchulCode = result.SD_SCHUL_CODE; school.cityProvince = result.LCTN_SC_NM; school.schoolName = result.SCHUL_NM; open.value = false }
</script>
<template><UPage class="v2-page"><UContainer><section class="pt-8"><p class="text-sm font-semibold uppercase tracking-[0.2em] text-primary">개인화 설정</p><h1 class="mt-2 text-3xl font-black tracking-tight">나에게 맞는 급식 보기</h1><p class="mt-2 text-gray-500">선택한 알레르기 정보가 메뉴에서 바로 강조됩니다.</p></section><UPageBody><UCard :ui="{ root: 'rounded-3xl shadow-sm ring-1 ring-gray-200/70', body: 'p-6 sm:p-8' }"><div class="flex flex-col gap-5 sm:flex-row sm:items-end"><UFormField label="교육청 코드"><UInput v-model="state.atptOfcdcScCode" disabled /></UFormField><UFormField label="학교 코드"><UInput v-model="state.sdSchulCode" disabled /></UFormField><UModal v-model:open="open"><UButton color="neutral" variant="outline">학교 찾기</UButton><template #title>학교 찾기</template><template #body><UForm :state="school" class="space-y-4" @submit="findSchool"><UFormField label="시도"><UInput v-model="school.cityProvince" /></UFormField><UFormField label="학교 이름"><UInput v-model="school.schoolName" /></UFormField><UButton type="submit">검색</UButton></UForm></template></UModal></div><USeparator class="my-8" /><div><h2 class="text-lg font-bold">주의할 알레르기</h2><p class="mt-1 text-sm text-gray-500">메뉴에 포함된 번호와 일치하면 빨간색 주의 표시가 나타납니다.</p><div class="mt-5 grid gap-3 sm:grid-cols-2 lg:grid-cols-3"><UCheckbox v-for="item in ALLERGENS" :key="item.code" v-model="selections[item.code]" :label="`${item.code}. ${item.name}`" /></div></div><div class="mt-8 flex justify-end"><UButton size="lg" icon="i-lucide-check" @click="save">설정 저장</UButton></div></UCard></UPageBody></UContainer></UPage></template>
